-- ============================================================================
-- MFGPulse AI Test Suite: TC-02 ML Pipeline
-- ============================================================================
SELECT 'TC-02-01' AS TEST_ID, 'Predictions: 1 per asset' AS TEST_NAME, 10 AS EXPECTED, COUNT(*) AS ACTUAL, CASE WHEN COUNT(*)=10 AND COUNT(DISTINCT ASSET_ID)=10 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-02' AS TEST_ID, 'RUL >= 0' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(RUL_HOURS<0) AS ACTUAL, CASE WHEN COUNT_IF(RUL_HOURS<0)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-03' AS TEST_ID, 'Degradation 0-1' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(DEGRADATION_SCORE<0 OR DEGRADATION_SCORE>1) AS ACTUAL, CASE WHEN COUNT_IF(DEGRADATION_SCORE<0 OR DEGRADATION_SCORE>1)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-04' AS TEST_ID, 'Fatigue 0-1' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(FATIGUE_SCORE<0 OR FATIGUE_SCORE>1) AS ACTUAL, CASE WHEN COUNT_IF(FATIGUE_SCORE<0 OR FATIGUE_SCORE>1)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-05' AS TEST_ID, 'Health 0-100' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(COMPOSITE_HEALTH_SCORE<0 OR COMPOSITE_HEALTH_SCORE>100) AS ACTUAL, CASE WHEN COUNT_IF(COMPOSITE_HEALTH_SCORE<0 OR COMPOSITE_HEALTH_SCORE>100)=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-06' AS TEST_ID, 'Valid stages' AS TEST_NAME, 0 AS EXPECTED, COUNT_IF(STAGE_PRED NOT IN ('Healthy','Warning','Critical')) AS ACTUAL, CASE WHEN COUNT_IF(STAGE_PRED NOT IN ('Healthy','Warning','Critical'))=0 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.LIVE_PREDICTIONS;
SELECT 'TC-02-10' AS TEST_ID, 'Simulator 100 paths' AS TEST_NAME, 100 AS EXPECTED, MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(5.0,0.05,0.5,0,7,0):num_simulations::INT AS ACTUAL, CASE WHEN MFGPULSE_DB.ML_MODELS.SIMULATE_FAILURE_TWIN(5.0,0.05,0.5,0,7,0):num_simulations::INT=100 THEN 'PASS' ELSE 'FAIL' END AS STATUS;
SELECT 'TC-02-11' AS TEST_ID, 'Fatigue all assets' AS TEST_NAME, 10 AS EXPECTED, COUNT(DISTINCT ASSET_ID) AS ACTUAL, CASE WHEN COUNT(DISTINCT ASSET_ID)=10 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.FATIGUE_SCORES;
SELECT 'TC-02-12' AS TEST_ID, 'Anomaly scores' AS TEST_NAME, 1800 AS EXPECTED, COUNT(*) AS ACTUAL, CASE WHEN COUNT(*)>=1800 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.ANOMALY_SCORES;
SELECT 'TC-02-13' AS TEST_ID, 'M1-M8 in registry' AS TEST_NAME, 8 AS EXPECTED, COUNT(*) AS ACTUAL, CASE WHEN COUNT(*)=8 THEN 'PASS' ELSE 'FAIL' END AS STATUS FROM MFGPULSE_DB.ML_MODELS.MODEL_REGISTRY WHERE MODEL_NAME LIKE 'M%';
